import {isAbsolute,resolve,sep} from 'node:path';
import {pathToFileURL} from 'node:url';

// Optional read-only location for fixtures already generated by this engine.
// No fallback discovery, copying, symlinks, or fixture generation occurs here.
export function testAssetUrl(relativePath){
 if(typeof relativePath!=='string'||!relativePath||relativePath.startsWith('/')||relativePath.includes('\\')||relativePath.split('/').includes('..')||/^[a-z][a-z0-9+.-]*:/i.test(relativePath))throw new TypeError('Test assets require an engine-relative path.');
 const root=process.env.SHERLOQ_TEST_ASSET_ROOT;
 if(root&&!isAbsolute(root))throw new TypeError('SHERLOQ_TEST_ASSET_ROOT must be an absolute engine asset directory.');
 const base=root?pathToFileURL(resolve(root)+sep):new URL('../../',import.meta.url);
 return new URL(relativePath,base);
}
